style.css:
/* Google Home After Dark — home.google.com */

/* swap these colors if you want */
:root {
  --my-bg: #101018;
  --my-surface: #1b1b29;
  --my-card: #242438;
  --my-accent: #a78bfa;
  --my-text: #f4f0ff;
  --my-muted: #aaa5bd;
}

/* dark background */
html, body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* headers and navigation */
header, nav, aside {
  background: var(--my-surface) !important;
  color: var(--my-text) !important;
  border-color: #35334b !important;
}

/* cards and panels */
main, section, article,
[role="main"], [role="dialog"] {
  border-color: #35334b !important;
}

/* buttons */
button, [role="button"] {
  background: var(--my-card) !important;
  color: var(--my-text) !important;
  border: 1px solid #41405b !important;
  border-radius: 14px !important;
  transition: 0.2s ease !important;
}

button:hover, [role="button"]:hover {
  background: #37304f !important;
  border-color: var(--my-accent) !important;
}

/* links */
a {
  color: var(--my-accent) !important;
}

/* inputs */
input, select, textarea {
  background: var(--my-card) !important;
  color: var(--my-text) !important;
  border: 1px solid #45415e !important;
  border-radius: 12px !important;
}

/* images */
img {
  border-radius: 14px !important;
}

/* smoother scrolling */
html {
  scroll-behavior: smooth !important;
}
